private (double Value, string Symbol) GetLargestWholeNumberPair()
{
    // Compute from Bits to avoid redundant property divisions until needed.
    double abs = Math.Abs(Bits);
    long bitsInTB = BitsInByte * BytesInTerabyte;
    long bitsInGB = BitsInByte * BytesInGigabyte;
    long bitsInMB = BitsInByte * BytesInMegabyte;
    long bitsInKB = BitsInByte * BytesInKilobyte;

    if (abs >= bitsInTB) return (Terabytes, TerabyteSymbol);
    if (abs >= bitsInGB) return (Gigabytes, GigabyteSymbol);
    if (abs >= bitsInMB) return (Megabytes, MegabyteSymbol);
    if (abs >= bitsInKB) return (Kilobytes, KilobyteSymbol);
    if (abs >= BitsInByte) return (Bytes, ByteSymbol);
    return (Bits, BitSymbol);
}

