/// <summary>
/// Returns a formatted string representation of this data size.
/// </summary>
/// <param name="format">A standard or custom numeric format string.</param>
/// <param name="provider">An object that supplies culture-specific formatting information.</param>
/// <returns>A formatted string representing this data size.</returns>
public string ToString(string? format, IFormatProvider? formatProvider = null)
{
    format ??= "0.## ";
    formatProvider ??= CultureInfo.CurrentCulture;

    if (!format.Contains('#') && !format.Contains('0'))
    {
        format = "0.## " + format;
    }

    format = format.Replace("#.##", "0.##");

    // Match unit suffix and extract the numeric format + unit in a single pass
    if (TryFormatWithUnit(format, formatProvider, TerabyteSymbol, Terabytes, out var result)) return result;
    if (TryFormatWithUnit(format, formatProvider, GigabyteSymbol, Gigabytes, out result)) return result;
    if (TryFormatWithUnit(format, formatProvider, MegabyteSymbol, Megabytes, out result)) return result;
    if (TryFormatWithUnit(format, formatProvider, KilobyteSymbol, Kilobytes, out result)) return result;

    if (format.Contains(ByteSymbol, StringComparison.Ordinal))
    {
        return FormatWithUnit(format, formatProvider, ByteSymbol, Bytes);
    }

    if (format.Contains(BitSymbol, StringComparison.Ordinal))
    {
        return FormatWithUnit(format, formatProvider, BitSymbol, Bits);
    }

    var (value, symbol) = GetLargestWholeNumberPair();
    return string.Concat(value.ToString(format, formatProvider), " ", symbol);
}

private static bool TryFormatWithUnit(
    string format, IFormatProvider provider, string unitSymbol, double value, out string result)
{
    int idx = format.IndexOf(unitSymbol, StringComparison.OrdinalIgnoreCase);
    if (idx < 0)
    {
        result = string.Empty;
        return false;
    }

    result = FormatWithUnit(format, provider, unitSymbol, value);
    return true;
}

private static string FormatWithUnit(
    string format, IFormatProvider provider, string unitSymbol, double value)
{
    // Split format into numeric part and rebuild with the literal unit symbol,
    // avoiding intermediate Replace allocations.
    int idx = format.IndexOf(unitSymbol, StringComparison.OrdinalIgnoreCase);
    ReadOnlySpan<char> numericFormat = format.AsSpan(0, idx);
    ReadOnlySpan<char> trailing = format.AsSpan(idx + unitSymbol.Length);

    return string.Concat(
        value.ToString(numericFormat.ToString(), provider),
        unitSymbol,
        trailing.ToString());
}

